<?php
require_once dirname(__DIR__) . '/middleware/bootstrap.php';
require_role('admin');
$db=Database::connection();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$active=(int)($_POST['active']??0);$stmt=$db->prepare('UPDATE courses SET active=? WHERE id=?');$stmt->execute([$active,$id]);$log=$db->prepare('INSERT INTO audit_logs(actor_user_id,action,entity_type,entity_id,ip_address) VALUES(?,?,?,?,?)');$log->execute([current_user_id(),$active?'course_activated':'course_deactivated','course',$id,$_SERVER['REMOTE_ADDR']??null]);flash('success',$active?'Course activated.':'Course deactivated.');redirect('admin/courses.php');}
$q=trim((string)($_GET['q']??''));$sql="SELECT c.*,d.name department_name,(SELECT COUNT(*) FROM registrations r WHERE r.course_id=c.id AND r.term_id=(SELECT id FROM academic_terms WHERE is_current=1 LIMIT 1) AND r.status IN ('pending','approved')) enrolled FROM courses c LEFT JOIN departments d ON d.id=c.department_id";$params=[];if($q!==''){$sql.=' WHERE c.code LIKE ? OR c.title LIKE ?';$params=['%'.$q.'%','%'.$q.'%'];}$sql.=' ORDER BY c.active DESC,c.code';
$stmt=$db->prepare($sql);$stmt->execute($params);$courses=$stmt->fetchAll();
page_start('Manage courses','admin/courses.php');
?>
<div class="content-width"><?php page_title('Manage courses','Create and maintain course details, schedules, and seat capacities.'); ?>
<div class="panel mb-3"><div class="d-flex flex-wrap justify-content-between gap-3"><form class="d-flex gap-2"><input class="form-control" name="q" placeholder="Search code or title" value="<?= e($q) ?>"><button class="btn btn-outline-primary">Search</button></form><a class="btn btn-primary" href="<?= e(url('admin/course_form.php')) ?>"><i class="bi bi-plus-lg me-1"></i>Add course</a></div></div>
<div class="panel p-0 overflow-hidden"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Course</th><th>Department</th><th>Semester</th><th>Credits</th><th>Enrolled / Capacity</th><th>Status</th><th>Actions</th></tr></thead><tbody>
<?php foreach($courses as $c): ?><tr><td><strong><?= e($c['code']) ?></strong><div class="small text-muted"><?= e($c['title']) ?></div></td><td><?= e($c['department_name']?:'All') ?></td><td><?= (int)$c['semester'] ?></td><td><?= (int)$c['credits'] ?></td><td><?= (int)$c['enrolled'] ?> / <?= (int)$c['capacity'] ?></td><td><span class="badge text-bg-<?= $c['active']?'success':'secondary' ?>"><?= $c['active']?'Active':'Inactive' ?></span></td><td class="table-actions"><a class="btn btn-sm btn-outline-secondary" href="<?= e(url('admin/course_view.php?id='.(int)$c['id'])) ?>">View</a> <a class="btn btn-sm btn-outline-primary" href="<?= e(url('admin/course_form.php?id='.(int)$c['id'])) ?>">Edit</a> <form class="d-inline" method="post" data-confirm-submit="Change course availability?"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$c['id'] ?>"><input type="hidden" name="active" value="<?= $c['active']?0:1 ?>"><button class="btn btn-sm btn-outline-<?= $c['active']?'danger':'success' ?>"><?= $c['active']?'Deactivate':'Activate' ?></button></form></td></tr><?php endforeach; ?>
<?php if(!$courses): ?><tr><td colspan="7"><div class="empty-state"><h3>No courses found</h3><a href="<?= e(url('admin/course_form.php')) ?>">Add the first course</a></div></td></tr><?php endif; ?>
</tbody></table></div></div></div>
<?php page_end(); ?>
